    result={}
    for row in rows:
        day,product,prod,orderq,shippedq,backq,stockq=row
        if remove_day124 and day==124 and product=='MASR025K':
            prod=0
        stocks[product]+=prod
        if orderq>0:
            orders_queue.append({'product':product,'remaining':orderq,'day':day})
        cap=capacity
        orders_queue.sort(key=lambda x:(x['day'],x['remaining'],x['product']))
        per_product_shipped={p:0 for p in stocks}
        for o in list(orders_queue):
            if cap<=0: break
            p=o['product']; remaining=o['remaining']; available=stocks[p]
            w=weights[p]
            max_units=min(available,cap//w,remaining)
            if max_units>0:
                stocks[p]-=max_units
                o['remaining']-=max_units
                cap-=max_units*w
                per_product_shipped[p]+=max_units
        orders_queue=[o for o in orders_queue if o['remaining']>0]
        backp={p:sum(o['remaining'] for o in orders_queue if o['product']==p) for p in stocks}
        result[(day,product)]={'stocks':stocks[product],'backordered':backp[product],'shipped':per_product_shipped[product]}
    return result
